insert into public.blog_posts
  (title, restaurant_name, cuisine, city, area, halal_claim, rating, rating_source, source_name, source_url, summary, images, published_at, is_sample)
values
  ('Turkish and Mediterranean plates in Boonton', 'Fasil Mediterranean Restaurant', 'Turkish / Mediterranean', 'Boonton, NJ', 'New Jersey', 'fully_halal', 4.6, '4.6 on OpenTable, about 365 reviews; other OpenTable pages show slightly different figures, so this may be dated', 'OpenTable', 'https://www.opentable.co.uk/fasil-mediterranean-restaurant', 'OpenTable lists this Boonton spot under Turkish, Mediterranean and Halal cuisine and describes a commitment to authentic halal food. Diners mention the hummus with warm pita, friendly service and an accommodating team. It offers reservations, takeout and catering.', '[{"url":"https://images.pexels.com/photos/11842140/pexels-photo-11842140.jpeg?auto=compress&cs=tinysrgb&w=1200","alt":"Stock photo of hummus with pita","stock":true,"credit":"Pexels","credit_url":"https://www.pexels.com/photo/humus-with-pita-11842140/"}]'::jsonb, '2026-11-16', false),
  ('A halal Turkish grill in Marlboro', 'Köy Grill', 'Turkish / Mediterranean', 'Marlboro, NJ', 'New Jersey', 'fully_halal', 4.8, '4.8 on OpenTable, about 21 reviews (small sample, may be dated)', 'OpenTable', 'https://opentable.com/r/koy-grill-marlboro', 'A Turkish and Mediterranean grill on Route 9 that its OpenTable listing calls 100% halal. Reviewers like the mixed grill for the amount of food, the generous portions and the attentive servers, though one finds it not cheap. The review count is still small.', '[{"url":"https://images.pexels.com/photos/7462776/pexels-photo-7462776.jpeg?auto=compress&cs=tinysrgb&w=1200","alt":"Stock photo of a mixed grill kebab platter","stock":true,"credit":"Pexels","credit_url":"https://www.pexels.com/photo/close-up-shot-of-kebab-meal-7462776/"}]'::jsonb, '2026-11-16', false),
  ('Hyderabadi biryani in Midtown', 'Hyderabadi Zaiqa', 'Indian / Hyderabadi', 'New York, NY', 'New York City', 'unsure', 5.0, '5 out of 5 stars from Time Out (seen via search summary, date uncertain); also about 4.5 on Google and DoorDash', 'Time Out New York', 'https://www.timeout.com/newyork/restaurants/hyderabadi-zaiqa', 'Time Out reviews this small Midtown counter for its Hyderabadi dum biryani, and it also appears on the publication''s halal restaurant list. Other listings point to goat and chicken 65 biryani as favourites, with one diner finding the portion small for the price. Seating is limited. Confirm halal status with the restaurant.', '[{"url":"https://images.pexels.com/photos/4224304/pexels-photo-4224304.jpeg?auto=compress&cs=tinysrgb&w=1200","alt":"Stock photo of chicken biryani","stock":true,"credit":"Pexels","credit_url":"https://www.pexels.com/photo/chicken-biryani-on-black-plate-4224304/"}]'::jsonb, '2026-11-16', false);
